mapper.select:
    SELECT
        su.*
    FROM sys_user su

    
      AND su.sys_user_delete = 0

      
        AND su.sys_user_username LIKE CONCAT('%', #{query.username}, '%')
      

      
        AND su.sys_user_nickname LIKE CONCAT('%', #{query.nickname}, '%')
      

      
        AND su.sys_user_phone LIKE CONCAT('%', #{query.phone}, '%')
      

      
        AND su.sys_user_sex = #{query.sex}
      

      
        AND su.sys_user_status = #{query.status}
      

      
        AND su.sys_dept_id IN (SELECT sys_dept_id FROM sys_dept WHERE sys_dept_tree_id LIKE CONCAT(
            (SELECT sys_dept_tree_id FROM sys_dept WHERE sys_dept_id = #{query.sysDeptId}), '%'))
      



        AND su.sys_dept_id = #{query.currentDeptId}



        AND su.sys_dept_id IN (SELECT sys_dept_id FROM sys_dept WHERE sys_dept_tree_id LIKE CONCAT(#{query.currentDeptTreeId}, '%'))



        AND su.sys_user_id = #{query.currentUserId}



        AND su.sys_dept_id IN (
            SELECT d.sys_dept_id FROM sys_dept d
            WHERE d.sys_dept_id IN
            #{deptId}
            OR EXISTS (
                SELECT 1 FROM sys_dept parent
                WHERE parent.sys_dept_id IN
                #{deptId}
                AND d.sys_dept_tree_id LIKE CONCAT(parent.sys_dept_tree_id, '%')
            )
        )


      ORDER BY su.create_time DESC

SELECT * FROM sys_user
  WHERE (sys_user_username = #{username} OR sys_user_phone = #{username})
  
    AND sys_tenant_id = #{tenantId}

SELECT * FROM sys_user
  WHERE (sys_user_username = #{tenant.sysTenantUsername} )
  AND sys_tenant_id = #{tenant.sysTenantId}

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM sys_user_role sur
INNER JOIN sys_role sr ON sr.sys_role_id = sur.sys_role_id
WHERE sur.sys_user_id = #{userId}
  AND sr.sys_role_id IN
  
    #{roleId}
